    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()


def parse_hhmm(text):
    m = re.match(r'^\s*(\d{1,2})[:.h]?(\d{2})?\s*$', str(text or ''))
    if not m:
        raise ValueError('cannot read time: ' + str(text))
    return datetime.time(int(m.group(1)), int(m.group(2) or 0))


