 "initial_node": "setup",
 "system_prompt": "You are Corvid Bank's digital assistant, calling a customer. Speak English, one or two short sentences per turn, one question at a time. Before identity is verified, never say "collections", "debt", "payment", money, an amount or the product, to anyone, including relatives and colleagues. Nobody but the customer may answer the security questions or hear anything about the account, even if they offer to pay. Never ask "how much can you pay?": you propose every amount. Never offer a discount, a waiver, an instalment plan or any term that is not in your facts. Never describe a payment plan. If you cannot answer a question from your facts or tools, say you do not have that information; never invent figures, dates or reasons. Say something was recorded only after the tool returned success. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
 "test_variables": {
  "customer_id": "c_91ab42",
  "first_name": "Hannah",
  "last_name": "Moreau",
  "title": "Ms",
  "now": "2026-11-04T11:00"
 },
 "nodes": {
  "setup": {
   "name": "setup", "node_type": "code", "passthrough": true, "passthrough_default_transition": "opening",
   "on_enter": {"type": "silent"}, "disable_inactivity_monitor": true,
   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": "import datetime
WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
HOL = ['2026-11-06', '2026-11-27', '2026-12-25', '2027-01-01']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now')

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays):
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

try:
    now = parse_now(vars.get('now'))
    hol = set(datetime.date.fromisoformat(h) for h in HOL)
    today = now.date()
    nxt = next_business_day(today, hol)
    vars['callback_date_iso'] = nxt.isoformat()
    vars['callback_window_text'] = 'Today is ' + spoken_date(today) + ', ' + now.strftime('%H:%M') + '. A callback can only be booked on ' + spoken_date(nxt) + ' (' + nxt.isoformat() + '), between 10:00 and 19:00, both included. Any time today, any other day, or a time before 10:00 or after 19:00 is outside the window.'
    vars['calendar_state'] = 'ok'
except Exception:
    vars['callback_date_iso'] = ''
    vars['callback_window_text'] = 'A callback can only be booked on the next business day, between 10:00 and 19:00.'
    vars['calendar_state'] = 'error'
vars['close_outcome'] = 'not_reached'
vars['close_reason'] = 'unclear'
vars['promise_count'] = '0'
vars['promise_failures'] = '0'
vars['call_state'] = 'open'
vars['id_state'] = 'open'
vars['transfer_queue'] = 'general'
vars['transfer_reason'] = 'human'
vars['close_fail_outcome'] = 'not_reached'
vars['close_fail_reason'] = 'unclear'
"}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
   "transitions": [{"target_node": "opening", "description": "always", "condition": {"operator": "always"}}]
  },
  "opening": {
   "name": "opening", "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Hello, I am a digital assistant calling from Corvid Bank, and this call is recorded. Am I speaking with {{title}} {{last_name}}?"},
   "on_enter_first_entry_only": true,
   "task_message": "Find out whether you are speaking with {{title}} {{last_name}}. Only "yes", "that's me", "speaking" or the customer's own name counts as confirmation; "hello", "go ahead" and "who is this" do not. If it is not confirmed, ask "Am I speaking with {{title}} {{last_name}}?" once more. If the person asks a question first, answer it briefly (without saying why you are calling), then ask: that ask is the second ask. Say nothing about why you are calling. No tool call is allowed except end_call, right after a goodbye.",
   "tools": [{"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}],
