    vars['promise_block'] = ''
    b = config.get('body')
    if isinstance(b, dict):
        try:
            amt = round(float(re.sub(r'[^0-9.]', '', str(b.get('amount')))), 2)
            b['amount'] = amt
        except Exception:
            amt = None
        day = None
        m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', str(b.get('date') or ''))
        if m:
            day = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            b['date'] = day.isoformat()
        fl = float(vars.get('floor_amount') or 0)
        fu = float(vars.get('full_amount') or 0)
        dl = datetime.date.fromisoformat(str(vars.get('deadline_iso')))
        td = datetime.date.fromisoformat(str(vars.get('today_iso')))
        late = vars.get('say_after_deadline') or ''
        msg = ''
        if amt is None:
            msg = 'NOT recorded: no valid amount. Read back the amount again.'
        elif amt < fl - 0.001:
            msg = 'NOT recorded: the amount is below the floor. Say exactly: ' + (vars.get('say_below_floor') or '')
