            msg = 'NOT recorded: the amount is above the full past-due amount. Use only amounts allowed by the facts.'
        elif day is None:
            msg = 'NOT recorded: no valid date. Ask for the exact day.'
        elif day > dl:
            msg = 'NOT recorded: the date is after the deadline. Say exactly: ' + late
        elif day < td:
            msg = 'NOT recorded: that date has passed. Ask for a day from today up to the deadline.'
        elif not bday(day):
            nb = day + datetime.timedelta(days=1)
            while not bday(nb):
                nb = nb + datetime.timedelta(days=1)
